18	        Objects.requireNonNull(pattern, "pattern must not be null");
19	
20	        if (pattern.isEmpty()) {
21	            throw new IllegalArgumentException("pattern must not be empty");
22	        }
23	
24	        return new KmpPattern(pattern, buildLongestPrefixSuffixTable(pattern));
25	    }
