32	        Objects.requireNonNull(text, "text must not be null");
33	
34	        if (value.length() > text.length()) {
35	            return List.of();
36	        }
37	
38	        List<Integer> matches = new ArrayList<>();
39	        int textIndex = 0;
40	        int patternIndex = 0;
41	
42	        while (textIndex < text.length()) {
43	            if (text.charAt(textIndex) == value.charAt(patternIndex)) {
44	                textIndex++;
45	                patternIndex++;
46	
47	                if (patternIndex == value.length()) {
48	                    matches.add(textIndex - patternIndex);
49	                    patternIndex = longestPrefixSuffix[patternIndex - 1];
50	                }
51	                continue;
52	            }
53	
54	            if (patternIndex > 0) {
55	                patternIndex = longestPrefixSuffix[patternIndex - 1];
56	            } else {
